def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the color used for full horizontal and vertical divider lines.
    line_counts = {}
    for row in grid:
        if row and row[0] != 0 and all(x == row[0] for x in row):
            line_counts[row[0]] = line_counts.get(row[0], 0) + 1
    for c in range(w):
        color = grid[0][c]
        if color != 0 and all(grid[r][c] == color for r in range(h)):
            line_counts[color] = line_counts.get(color, 0) + 1
    if not line_counts:
        return [row[:] for row in grid]
    divider = max(line_counts, key=line_counts.get)

    def segments(length, is_divider):
        result = []
        start = None
        for i in range(length):
            if is_divider(i):
                if start is not None:
                    result.append((start, i))
                    start = None
            elif start is None:
                start = i
        if start is not None:
            result.append((start, length))
        return result

    row_cells = segments(h, lambda r: all(x == divider for x in grid[r]))
    col_cells = segments(w, lambda c: all(grid[r][c] == divider for r in range(h)))

    out = [row[:] for row in grid]
    if not row_cells or not col_cells:
