    # Each motif occupies three corners of a 2x2 compartment block.
    # Complete the fourth by reflecting the motif across the appropriate axis.
    for color, cells in occupied.items():
        if len(cells) != 3:
            continue
        min_r = min(r for r, c in cells)
        max_r = max(r for r, c in cells)
        min_c = min(c for r, c in cells)
        max_c = max(c for r, c in cells)
        if max_r - min_r != 1 or max_c - min_c != 1:
            continue

        corners = {
            (min_r, min_c), (min_r, max_c),
            (max_r, min_c), (max_r, max_c)
        }
        missing = corners - cells
        if len(missing) != 1:
            continue
        tr, tc = next(iter(missing))

        # Use the occupied compartment in the same compartment row.
        sr = tr
        sc = min_c if tc == max_c else max_c
        sr0, sr1 = row_cells[sr]
        sc0, sc1 = col_cells[sc]
        tr0, tr1 = row_cells[tr]
        tc0, tc1 = col_cells[tc]
